{"artifact":{"path":"union-acceptance/cut-identity.test.mjs","text":"import assert from "node:assert/strict";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";
import { scanTerritory } from "../src/scan-territory.mjs";

const NI_SHA256 = /^ni:\/\/\/sha-256;[\w-]{43}$/u;

function leafManifest(opNames) {
  return JSON.stringify({
    name: "test-settlement",
    "x-agentic-metro-enterprise": {
      "node-id": "test-settlement",
      "operation-catalog": Object.fromEntries(opNames.map((n) => [n, {}])),
    },
  });
}

test("canonical-cut-ni-identity", () => {
  const root = mkdtempSync(join(tmpdir(), "cut-id-"));
  try {
    writeFileSync(join(root, "package.json"), leafManifest(["op-a", "op-b"]));
    const report = scanTerritory(root);
    assert.ok(report.cutFrontier.length > 0, "frontier must be non-empty");
    const entry = report.cutFrontier[0];
    assert.ok(
      typeof entry.cutId === "string",
      "cut frontier entry must carry a cutId string"
    );
    assert.match(
      entry.cutId,
      NI_SHA256,
      "cutId must be an RFC 6920 SHA-256 ni URI"
    );
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test("repeatable-cut-identity", () => {
  const root = mkdtempSync(join(tmpdir(), "cut-id-"));
  try {
    writeFileSync(join(root, "package.json"), leafManifest(["op-a", "op-b"]));
    const first = scanTerritory(root).cutFrontier[0];
    const second = scanTerritory(root).cutFrontier[0];
    assert.ok(
      typeof first.cutId === "string",
      "first scan must yield a cutId"
    );
    assert.equal(
      first.cutId,
      second.cutId,
      "cutId must be stable across repeated scans of identical material"
    );
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test("material-change-changes-cut-identity", () => {
  const root = mkdtempSync(join(tmpdir(), "cut-id-"));
  try {
    writeFileSync(join(root, "package.json"), leafManifest(["op-a", "op-b"]));
    const before = scanTerritory(root).cutFrontier[0];
    assert.ok(
      typeof before.cutId === "string",
      "initial scan must yield a cutId"
    );
    writeFileSync(join(root, "live.jsonl"), "{}\n");
    const after = scanTerritory(root).cutFrontier[0];
    assert.ok(
      typeof after.cutId === "string",
      "post-change scan must yield a cutId"
    );
    assert.notEqual(
      before.cutId,
      after.cutId,
      "cutId must differ after material change"
    );
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});
"},"rationale":"Each test constructs a temporary territory via mkdtempSync and triggers die-operation-cardinality by writing a leaf manifest with two semantic operations. The first test asserts the frontier entry carries a cutId string matching the RFC 6920 ni:///sha-256; pattern. The second test scans the same material twice and asserts the two cutId values are equal. The third test adds a forbidden .jsonl file after the baseline scan, changing violationCount, rules, and paths in the frontier entry, then asserts the cutId differs. All three fail on the incumbent solely because cutFrontier entries lack the cutId field; import, syntax, fixture setup, and assertion shape are all valid."}

